import java.security.*;
import java.util.Base64;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public class CryptoService {
    private static final Logger logger = Logger.getLogger(CryptoService.class.getName());
    private static final int MAX_RETRIES = 3;
    private static final int RATE_LIMIT_WINDOW_MS = 60000;
    private static final int MAX_REQUESTS_PER_WINDOW = 100;

    private final ConcurrentHashMap<String, RateLimitEntry> rateLimitMap = new ConcurrentHashMap<>();
    private final SecretKey masterKey;

    public CryptoService() throws NoSuchAlgorithmException {
        KeyGenerator keyGen = KeyGenerator.getInstance("AES");
        keyGen.init(256);
        this.masterKey = keyGen.generateKey();
    }

    private static class RateLimitEntry {
        final AtomicInteger count = new AtomicInteger(0);
        volatile long windowStart = System.currentTimeMillis();

        boolean tryAcquire() {
            long now = System.currentTimeMillis();
            if (now - windowStart > RATE_LIMIT_WINDOW_MS) {
                synchronized (this) {
                    if (now - windowStart > RATE_LIMIT_WINDOW_MS) {
                        windowStart = now;
                        count.set(0);
                    }
                }
            }
            return count.incrementAndGet() <= MAX_REQUESTS_PER_WINDOW;
        }
    }

    private boolean checkRateLimit(String clientId) {
        RateLimitEntry entry = rateLimitMap.computeIfAbsent(clientId, k -> new RateLimitEntry());
        return entry.tryAcquire();
    }

    public byte[] encrypt(String clientId, byte[] plaintext, String operationContext) throws Exception {
        if (!checkRateLimit(clientId)) {
            logOperationFailure(clientId, operationContext, "Rate limit exceeded");
            throw new SecurityException("Rate limit exceeded for client: " + sanitizeForException(clientId));
        }

        int attempt = 0;
        Exception lastException = null;

        while (attempt < MAX_RETRIES) {
            try {
                attempt++;
                byte[] result = performEncryption(plaintext);
                logOperationSuccess(clientId, operationContext, attempt);
                return result;
            } catch (GeneralSecurityException e) {
                lastException = e;
                logRetryAttempt(clientId, operationContext, attempt, e.getMessage());
                Thread.sleep((long) Math.pow(2, attempt) * 100);
            }
        }

        logOperationFailure(clientId, operationContext, "Max retries exceeded");
        throw lastException;
    }

    private byte[] performEncryption(byte[] plaintext) throws GeneralSecurityException {
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        byte[] iv = new byte[12];
        SecureRandom.getInstanceStrong().nextBytes(iv);
        GCMParameterSpec spec = new GCMParameterSpec(128, iv);
        cipher.init(Cipher.ENCRYPT_MODE, masterKey, spec);
        byte[] ciphertext = cipher.doFinal(plaintext);
        byte[] combined = new byte[iv.length + ciphertext.length];
        System.arraycopy(iv, 0, combined, 0, iv.length);
        System.arraycopy(ciphertext, 0, combined, iv.length, ciphertext.length);
        return combined;
    }

    private String sanitizeForException(String input) {
        if (input == null) return "null";
        return input.replaceAll("[^a-zA-Z0-9_\\-]", "_").substring(0, Math.min(input.length(), 64));
    }

    private String normalizeLogContext(String context) {
        if (context == null) return "unknown";
        // Normalize Unicode to prevent homoglyph attacks in log analysis
        String normalized = java.text.Normalizer.normalize(context, java.text.Normalizer.Form.NFKC);
        // Strip all non-alphanumeric except safe structural characters
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < normalized.length() && i < 256; i++) {
            char c = normalized.charAt(i);
            if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
                (c >= '0' && c <= '9') || c == '_' || c == '-' || c == '.') {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    private void logOperationSuccess(String clientId, String context, int attempts) {
        String safeClient = sanitizeForException(clientId);
        String safeContext = normalizeLogContext(context);
        logger.info(String.format("crypto_op=success client=%s context=%s attempts=%d",
                safeClient, safeContext, attempts));
    }

    private void logRetryAttempt(String clientId, String context, int attempt, String reason) {
        String safeClient = sanitizeForException(clientId);
        String safeContext = normalizeLogContext(context);
        logger.warning(String.format("crypto_op=retry client=%s context=%s attempt=%d reason=%s",
                safeClient, safeContext, attempt, sanitizeForException(reason)));
    }

    private void logOperationFailure(String clientId, String context, String reason) {
        String safeClient = sanitizeForException(clientId);
        String safeContext = normalizeLogContext(context);
        logger.severe(String.format("crypto_op=failure client=%s context=%s reason=%s",
                safeClient, safeContext, sanitizeForException(reason)));
    }
}
